/* @lc app=leetcode id=2286 lang=kotlin */
class BookMyShow(val n: Int, val m: Int) { val sum = LongArray(4 * n) val max = LongArray(4 * n) fun build(i: Int, l: Int, r: Int): Unit = if (l == r) sum.set(i, m.toLong()).also { max[i] = m.toLong() } else ((l + r) / 2).let { mid -> build(2 * i + 1, l, mid).also { build(2 * i + 2, mid + 1, r) }.also { sum[i] = sum[2 * i + 1] + sum[2 * i + 2] }.also { max[i] = maxOf(max[2 * i + 1], max[2 * i + 2]) } } val dummy = build(0, 0, n - 1) fun gather(k: Int, maxRow: Int): IntArray = queryGather(0, 0, n - 1, k, maxRow) fun queryGather(i: Int, l: Int, r: Int, k: Int, maxRow: Int): IntArray = if (max[i] < k || l > maxRow) intArrayOf() else if (l == r) (m - max[i].toInt()).let { pos -> intArrayOf(l, pos).also { sum[i] = sum[i] - k }.also { max[i] = max[i] - k } } else ((l + r) / 2).let { mid -> queryGather(2 * i + 1, l, mid, k, maxRow).let { res -> if (res.isNotEmpty()) res else queryGather(2 * i + 2, mid + 1, r, k, maxRow) } }.also { sum[i] = sum[2 * i + 1] + sum[2 * i + 2] }.also { max[i] = maxOf(max[2 * i + 1], max[2 * i + 2]) } fun querySum(i: Int, l: Int, r: Int, ql: Int, qr: Int): Long = if (l > qr || r < ql) 0L else if (l >= ql && r <= qr) sum[i] else ((l + r) / 2).let { mid -> querySum(2 * i + 1, l, mid, ql, qr) + querySum(2 * i + 2, mid + 1, r, ql, qr) } fun updateScatter(i: Int, l: Int, r: Int, maxRow: Int, k: Long): Long = if (l > maxRow || sum[i] == 0L || k == 0L) k else if (l == r) minOf(sum[i], k).let { take -> (k - take).also { sum[i] = sum[i] - take }.also { max[i] = max[i] - take } } else ((l + r) / 2).let { mid -> updateScatter(2 * i + 1, l, mid, maxRow, k).let { rem -> updateScatter(2 * i + 2, mid + 1, r, maxRow, rem) } }.also { sum[i] = sum[2 * i + 1] + sum[2 * i + 2] }.also { max[i] = maxOf(max[2 * i + 1], max[2 * i + 2]) } fun scatter(k: Int, maxRow: Int): Boolean = if (querySum(0, 0, n - 1, 0, maxRow) < k) false else (updateScatter(0, 0, n - 1, maxRow, k.toLong()) == 0L) }